/**
 * Error constructors for the portable node:http shim.
 *
 * Node's generic argument errors and Jco's unsupported/deprecated refusals come from the shared
 * factory and templates in `../errors/core.js`, so they carry the same identity as every other
 * builtin. Only the HTTP-specific codes (`ERR_INVALID_HTTP_TOKEN`, `ERR_INVALID_CHAR`,
 * `ERR_HTTP_HEADERS_SENT`, `ERR_STREAM_WRITE_AFTER_END`) and the host-record reconstruction live
 * here. Message templates for those follow nodejs/node v24.19.0, commit
 * cdc1b38d40cb567b7ad0b39c86addf830a0af0ae, lib/internal/errors.js (MIT license).
 */
import { codedError, deprecatedNodeApi, invalidArgType as sharedInvalidArgType, invalidArgValue as sharedInvalidArgValue, outOfRange as sharedOutOfRange, unsupportedNodeApi, } from "../errors/core.js";
import { decodeErrno } from "../internal/host-error.js";
function httpError(name, code, message) {
    const error = name === "TypeError"
        ? new TypeError(message)
        : name === "RangeError"
            ? new RangeError(message)
            : new Error(message);
    return codedError(error, code);
}
export function invalidArgType(name, expected, value) {
    return sharedInvalidArgType(name, expected, value);
}
export function invalidArgValue(name, value) {
    return sharedInvalidArgValue(name, value);
}
export function outOfRange(name, range, value) {
    return sharedOutOfRange(name, range, value);
}
export function invalidHttpToken(label, value) {
    return httpError("TypeError", "ERR_INVALID_HTTP_TOKEN", `${label} must be a valid HTTP token ["${value}"]`);
}
export function invalidHeaderChar(name) {
    return httpError("TypeError", "ERR_INVALID_CHAR", `Invalid character in header content ["${name}"]`);
}
export function headerAlreadySent() {
    return httpError("Error", "ERR_HTTP_HEADERS_SENT", "Cannot modify headers after they are sent to the client");
}
export function writeAfterEnd() {
    return httpError("Error", "ERR_STREAM_WRITE_AFTER_END", "write after end");
}
export function adapterRequired() {
    throw httpError("Error", "ERR_JCO_HTTP_ADAPTER_REQUIRED", "node:http requires an HTTP provider; select --with-nodejs-http-via or map jco:node/http@0.1.0 to an application host");
}
export function unsupported(api, detail) {
    throw unsupportedNodeApi(api, detail ?? "the Jco component runtime does not implement it");
}
export function deprecated(api, replacement) {
    throw deprecatedNodeApi(api, replacement);
}
export function fromImplementationError(value) {
    const error = httpError(value.name === "TypeError" || value.name === "RangeError" ? value.name : "Error", value.code ?? "ERR_JCO_HTTP_IMPLEMENTATION", value.message);
    const errno = value.errno;
    error.errno = typeof errno === "object" && errno !== null ? decodeErrno(errno) : errno;
    error.syscall = value.syscall;
    error.hostname = value.hostname;
    error.address = value.address;
    error.port = value.port;
    return error;
}
/** Read a WASI error code from either a raw payload or a ComponentError wrapper. */
export function wasiErrorCode(error) {
    const value = typeof error === "object" && error !== null && "payload" in error ? error.payload : error;
    if (typeof value === "string") {
        return value;
    }
    if (typeof value === "object" &&
        value !== null &&
        "tag" in value &&
        typeof value.tag === "string") {
        return value.tag;
    }
    return undefined;
}
